-- ACCORD CRM V2 (Claude) — ALL migrations in order. Generated by scripts/build-apply-all.mjs. Run once on a NEW, EMPTY project.
-- ============ 20261009000001_core_schema.sql ============
-- ACCORD CRM V2 (Claude independent version) — core schema
-- Timezone for all business-date logic: Africa/Cairo

create extension if not exists pg_trgm with schema extensions;
create extension if not exists btree_gist with schema extensions;

-- ---------------------------------------------------------------------------
-- Time helpers (Cairo business calendar)
-- ---------------------------------------------------------------------------
create or replace function public.cairo_date(ts timestamptz) returns date
language sql immutable parallel safe as $$ select (ts at time zone 'Africa/Cairo')::date $$;

create or replace function public.cairo_today() returns date
language sql stable as $$ select public.cairo_date(now()) $$;

-- start of a Cairo calendar day, as an absolute instant
create or replace function public.cairo_day_start(d date) returns timestamptz
language sql immutable parallel safe as $$ select (d::timestamp) at time zone 'Africa/Cairo' $$;

create or replace function public.norm_name(t text) returns text
language sql immutable parallel safe as $$
  select lower(btrim(regexp_replace(regexp_replace(coalesce(t, ''), '[.,]', ' ', 'g'), '\s+', ' ', 'g')))
$$;

create or replace function public.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Reference / configuration tables
-- ---------------------------------------------------------------------------
create table public.pipeline_stages (
  key text primary key,
  label text not null,
  position int not null,
  is_terminal boolean not null default false,
  active boolean not null default true
);

create table public.call_outcomes (
  key text primary key,
  label text not null,
  kind text not null check (kind in ('responded', 'did_not_respond')),
  position int not null default 0,
  active boolean not null default true
);

create table public.activity_types (
  key text primary key,
  label text not null,
  icon text not null default 'circle'
);

create table public.settings (
  key text primary key,
  value jsonb not null,
  description text,
  updated_by uuid,
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Profiles (CRM access is granted ONLY by an active row here)
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  full_name text not null default '',
  phone text,
  role text not null check (role in ('admin', 'bd_executive', 'viewer')),
  active boolean not null default true,
  must_change_password boolean not null default false,
  created_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index profiles_email_key on public.profiles (lower(email));

create or replace function public.current_app_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and active
$$;
create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select role = 'admin' from public.profiles where id = auth.uid() and active), false)
$$;
create or replace function public.is_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select role in ('admin', 'bd_executive') from public.profiles where id = auth.uid() and active), false)
$$;
create or replace function public.is_member() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and active)
$$;
revoke all on function public.current_app_role(), public.is_admin(), public.is_staff(), public.is_member() from public, anon;
grant execute on function public.current_app_role(), public.is_admin(), public.is_staff(), public.is_member() to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Leads & contacts
-- ---------------------------------------------------------------------------
create table public.leads (
  id uuid primary key default gen_random_uuid(),
  name text not null check (btrim(name) <> ''),
  name_norm text not null,
  external_lead_id text,
  website text,
  industry text,
  city text,
  address text,
  temperature text not null default 'cold' check (temperature in ('cold', 'warm', 'hot', 'lost', 'closed')),
  pipeline_stage text not null default 'research' references public.pipeline_stages (key),
  owner_id uuid references public.profiles (id),
  source text not null default 'manual' check (source in ('manual', 'google_sheet', 'import')),
  source_sheet text,
  source_row int,
  legacy jsonb not null default '{}'::jsonb,
  notes text,
  archived boolean not null default false,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index leads_external_lead_id_key on public.leads (external_lead_id) where external_lead_id is not null;
create index leads_name_norm_idx on public.leads (name_norm);
create index leads_owner_idx on public.leads (owner_id);
create index leads_stage_idx on public.leads (pipeline_stage) where not archived;
create index leads_temperature_idx on public.leads (temperature) where not archived;

create or replace function public.leads_before_write() returns trigger
language plpgsql as $$
begin
  new.name := btrim(new.name);
  new.name_norm := public.norm_name(new.name);
  return new;
end $$;
create trigger leads_before_write before insert or update on public.leads
  for each row execute function public.leads_before_write();
create trigger leads_updated_at before update on public.leads
  for each row execute function public.set_updated_at();

create table public.contacts (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  full_name text not null default '',
  job_title text,
  emails text[] not null default '{}',
  phones text[] not null default '{}',
  linkedin text[] not null default '{}',
  is_primary boolean not null default false,
  notes text,
  dedupe_key text,
  source text not null default 'manual',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index contacts_lead_idx on public.contacts (lead_id);
create unique index contacts_lead_dedupe_key on public.contacts (lead_id, dedupe_key) where dedupe_key is not null;
create trigger contacts_updated_at before update on public.contacts
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Call sessions & attempts (every attempt is its own immutable-by-default row)
-- ---------------------------------------------------------------------------
create table public.call_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id),
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  notes text,
  created_at timestamptz not null default now()
);
create index call_sessions_user_idx on public.call_sessions (user_id, started_at desc);

create table public.call_attempts (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  contact_id uuid references public.contacts (id) on delete set null,
  user_id uuid not null references public.profiles (id),
  call_session_id uuid references public.call_sessions (id) on delete set null,
  outcome text not null references public.call_outcomes (key),
  sub_outcome text check (sub_outcome in (
    'interested', 'follow_up_needed', 'meeting_requested', 'meeting_scheduled',
    'proposal_discussion', 'not_interested', 'other',
    'retry_later_today', 'tomorrow', 'select_date', 'no_retry')),
  called_at timestamptz not null default now(),
  duration_seconds int check (duration_seconds is null or duration_seconds >= 0),
  notes text,
  follow_up_id uuid,
  meeting_id uuid,
  source text not null default 'app' check (source in ('app', 'admin', 'import')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint call_not_in_future check (called_at <= now() + interval '10 minutes')
);
create index call_attempts_user_time_idx on public.call_attempts (user_id, called_at desc);
create index call_attempts_lead_time_idx on public.call_attempts (lead_id, called_at desc);
create index call_attempts_time_idx on public.call_attempts (called_at);
create trigger call_attempts_updated_at before update on public.call_attempts
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Targets (effective-dated, never overlapping per user)
-- ---------------------------------------------------------------------------
create table public.user_targets (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id),
  daily_call_target int not null check (daily_call_target >= 0),
  effective_from date not null,
  effective_to date,
  active boolean not null default true,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (effective_to is null or effective_to >= effective_from),
  constraint user_targets_no_overlap exclude using gist (
    user_id with =,
    daterange(effective_from, effective_to, '[]') with &&
  ) where (active)
);
create index user_targets_user_idx on public.user_targets (user_id, effective_from desc);
create trigger user_targets_updated_at before update on public.user_targets
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Follow-ups
-- ---------------------------------------------------------------------------
create table public.follow_ups (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  contact_id uuid references public.contacts (id) on delete set null,
  owner_id uuid references public.profiles (id),
  title text not null default 'Follow-up',
  notes text,
  due_date date not null,
  due_time time,
  status text not null default 'open' check (status in ('open', 'completed', 'cancelled')),
  completed_at timestamptz,
  completed_by uuid references public.profiles (id),
  origin text not null default 'manual' check (origin in ('manual', 'call', 'meeting', 'proposal', 'form', 'google_sheet')),
  call_id uuid references public.call_attempts (id) on delete set null,
  meeting_id uuid,
  proposal_id uuid,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((status = 'completed') = (completed_at is not null))
);
create index follow_ups_owner_due_idx on public.follow_ups (owner_id, status, due_date);
create index follow_ups_due_idx on public.follow_ups (due_date) where status = 'open';
create index follow_ups_lead_idx on public.follow_ups (lead_id, due_date);
create unique index follow_ups_sheet_key on public.follow_ups (lead_id, due_date) where origin = 'google_sheet';
create trigger follow_ups_updated_at before update on public.follow_ups
  for each row execute function public.set_updated_at();

alter table public.call_attempts
  add constraint call_attempts_follow_up_fk foreign key (follow_up_id) references public.follow_ups (id) on delete set null;

-- ---------------------------------------------------------------------------
-- Meetings
-- ---------------------------------------------------------------------------
create table public.meetings (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  contact_id uuid references public.contacts (id) on delete set null,
  owner_id uuid references public.profiles (id),
  status text not null default 'scheduled' check (status in ('requested', 'scheduled', 'completed', 'missed', 'cancelled', 'rescheduled')),
  scheduled_at timestamptz,
  timezone text not null default 'Africa/Cairo',
  meeting_type text not null default 'physical' check (meeting_type in ('physical', 'online', 'phone')),
  location text,
  online_link text,
  confirmation_status text not null default 'unconfirmed' check (confirmation_status in ('confirmed', 'unconfirmed', 'tentative')),
  attendance_status text not null default 'pending' check (attendance_status in ('pending', 'attended', 'not_attended')),
  attendance_recorded_at timestamptz,
  meeting_with text,
  purpose text,
  agenda text,
  internal_attendees text,
  external_attendees text,
  notes text,
  summary text,
  minutes_of_meeting text,
  discussion_points text,
  client_requirements text,
  agreements text,
  commitments text,
  requested_documents text,
  commercial_notes text,
  meeting_outcome text check (meeting_outcome in (
    'positive', 'neutral', 'negative', 'more_information_required', 'form_required',
    'proposal_requested', 'second_meeting_required', 'negotiation', 'no_opportunity', 'other')),
  next_step text check (next_step in (
    'send_requirement_form', 'wait_for_completed_form', 'prepare_proposal', 'send_proposal',
    'follow_up', 'schedule_second_meeting', 'provide_technical_information',
    'commercial_negotiation', 'close_opportunity', 'other')),
  next_step_detail text,
  next_follow_up_at date,
  next_meeting_required boolean,
  next_meeting_id uuid references public.meetings (id) on delete set null,
  not_attended_reason text check (not_attended_reason in (
    'client_did_not_attend', 'accord_did_not_attend', 'client_cancelled', 'rescheduled',
    'unable_to_reach_client', 'timing_conflict', 'other')),
  not_attended_notes text,
  rescheduled_from_id uuid references public.meetings (id) on delete set null,
  follows_meeting_id uuid references public.meetings (id) on delete set null,
  created_from_call_id uuid references public.call_attempts (id) on delete set null,
  proposal_id uuid,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (status = 'requested' or scheduled_at is not null),
  check (attendance_status <> 'not_attended' or not_attended_reason is not null)
);
create index meetings_schedule_idx on public.meetings (scheduled_at) where scheduled_at is not null;
create index meetings_lead_idx on public.meetings (lead_id, scheduled_at desc);
create index meetings_owner_idx on public.meetings (owner_id, scheduled_at);
create trigger meetings_updated_at before update on public.meetings
  for each row execute function public.set_updated_at();

alter table public.call_attempts
  add constraint call_attempts_meeting_fk foreign key (meeting_id) references public.meetings (id) on delete set null;
alter table public.follow_ups
  add constraint follow_ups_meeting_fk foreign key (meeting_id) references public.meetings (id) on delete set null;

-- ---------------------------------------------------------------------------
-- Information / requirement forms
-- ---------------------------------------------------------------------------
create table public.commercial_forms (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  meeting_id uuid references public.meetings (id) on delete set null,
  owner_id uuid references public.profiles (id),
  required boolean not null default true,
  status text not null default 'not_sent' check (status in ('not_required', 'not_sent', 'sent', 'partially_completed', 'completed')),
  sent_on date,
  completed_on date,
  link text,
  file_path text,
  notes text,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- never fabricate dates: a status that implies an event needs that event's date
  check (status not in ('sent', 'partially_completed', 'completed') or sent_on is not null),
  check (status <> 'completed' or completed_on is not null)
);
create index commercial_forms_lead_idx on public.commercial_forms (lead_id, created_at desc);
create index commercial_forms_status_idx on public.commercial_forms (status);
create trigger commercial_forms_updated_at before update on public.commercial_forms
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Proposals
-- ---------------------------------------------------------------------------
create sequence public.proposal_seq;
create table public.proposals (
  id uuid primary key default gen_random_uuid(),
  proposal_no bigint not null default nextval('public.proposal_seq'),
  lead_id uuid not null references public.leads (id) on delete cascade,
  contact_ids uuid[] not null default '{}',
  meeting_id uuid references public.meetings (id) on delete set null,
  form_id uuid references public.commercial_forms (id) on delete set null,
  title text not null default 'Proposal',
  owner_id uuid references public.profiles (id),
  value numeric(14, 2) check (value is null or value >= 0),
  currency text not null default 'EGP',
  status text not null default 'not_started' check (status in (
    'not_started', 'preparing', 'ready', 'sent', 'under_review', 'revision_requested', 'accepted', 'rejected', 'closed')),
  prepared_on date,
  sent_on date,
  file_path text,
  notes text,
  next_follow_up_date date,
  response_state text check (response_state in ('awaiting_response', 'responded', 'no_response_yet')),
  response_outcome text check (response_outcome in (
    'positive', 'needs_revision', 'needs_meeting', 'negotiation', 'rejected', 'accepted', 'other')),
  response_on date,
  response_notes text,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (status not in ('sent', 'under_review') or sent_on is not null),
  check (response_state is distinct from 'responded' or (response_outcome is not null and response_on is not null))
);
create unique index proposals_no_key on public.proposals (proposal_no);
create index proposals_lead_idx on public.proposals (lead_id, created_at desc);
create index proposals_owner_idx on public.proposals (owner_id, status);
create trigger proposals_updated_at before update on public.proposals
  for each row execute function public.set_updated_at();

alter table public.meetings add constraint meetings_proposal_fk foreign key (proposal_id) references public.proposals (id) on delete set null;
alter table public.follow_ups add constraint follow_ups_proposal_fk foreign key (proposal_id) references public.proposals (id) on delete set null;

-- ---------------------------------------------------------------------------
-- Attachments (metadata; bytes live in private Storage bucket "crm-files")
-- ---------------------------------------------------------------------------
create table public.attachments (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  entity_type text not null check (entity_type in ('lead', 'meeting', 'proposal', 'form')),
  entity_id uuid,
  bucket text not null default 'crm-files',
  path text not null unique,
  file_name text not null,
  mime_type text,
  size_bytes bigint,
  uploaded_by uuid references public.profiles (id),
  created_at timestamptz not null default now()
);
create index attachments_lead_idx on public.attachments (lead_id, created_at desc);
create index attachments_entity_idx on public.attachments (entity_type, entity_id);

-- ---------------------------------------------------------------------------
-- Sheet2 reference data (developers / projects) — never creates leads
-- ---------------------------------------------------------------------------
create table public.projects (
  id uuid primary key default gen_random_uuid(),
  developer_name text not null,
  developer_norm text not null,
  project_name text not null,
  project_norm text not null,
  attributes jsonb not null default '{}'::jsonb,
  linked_lead_id uuid references public.leads (id) on delete set null, -- manual link only, never auto-merged
  source_sheet text,
  source_row int,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (developer_norm, project_norm)
);
create trigger projects_updated_at before update on public.projects
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- Timeline, sync history, audit
-- ---------------------------------------------------------------------------
create table public.activities (
  id uuid primary key default gen_random_uuid(),
  lead_id uuid not null references public.leads (id) on delete cascade,
  actor_id uuid references public.profiles (id),
  type text not null references public.activity_types (key),
  occurred_at timestamptz not null default now(),
  summary text,
  ref_table text,
  ref_id uuid,
  data jsonb not null default '{}'::jsonb
);
create index activities_lead_time_idx on public.activities (lead_id, occurred_at desc, id);
create index activities_type_time_idx on public.activities (type, occurred_at);
create index activities_actor_time_idx on public.activities (actor_id, occurred_at);

create table public.sync_runs (
  id uuid primary key default gen_random_uuid(),
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  initiated_by uuid references public.profiles (id),
  spreadsheet_id text not null,
  sheet_name text not null,
  mode text not null check (mode in ('preview', 'sync')),
  status text not null default 'running' check (status in ('running', 'success', 'partial', 'failed')),
  rows_scanned int not null default 0,
  inserted int not null default 0,
  updated int not null default 0,
  skipped int not null default 0,
  conflicts int not null default 0,
  rejected int not null default 0,
  errors int not null default 0,
  summary jsonb not null default '{}'::jsonb
);
create index sync_runs_started_idx on public.sync_runs (started_at desc);

create table public.sync_errors (
  id bigint generated always as identity primary key,
  run_id uuid not null references public.sync_runs (id) on delete cascade,
  row_number int,
  kind text not null check (kind in ('rejected', 'conflict', 'error')),
  message text not null,
  payload jsonb,
  created_at timestamptz not null default now()
);
create index sync_errors_run_idx on public.sync_errors (run_id);

create table public.audit_logs (
  id bigint generated always as identity primary key,
  at timestamptz not null default now(),
  actor_id uuid,
  actor_email text,
  entity text not null,
  entity_id text,
  action text not null,
  old_value jsonb,
  new_value jsonb,
  meta jsonb
);
create index audit_logs_at_idx on public.audit_logs (at desc);
create index audit_logs_entity_idx on public.audit_logs (entity, entity_id);
create index audit_logs_actor_idx on public.audit_logs (actor_id, at desc);

-- audit log is append-only
create or replace function public.audit_logs_immutable() returns trigger
language plpgsql as $$
begin
  raise exception 'audit_logs is append-only';
end $$;
create trigger audit_logs_no_update before update or delete on public.audit_logs
  for each row execute function public.audit_logs_immutable();
create trigger audit_logs_no_truncate before truncate on public.audit_logs
  for each statement execute function public.audit_logs_immutable();

-- ---------------------------------------------------------------------------
-- Denormalised per-lead rollups (maintained by triggers; not user-writable)
-- ---------------------------------------------------------------------------
create table public.lead_rollups (
  lead_id uuid primary key references public.leads (id) on delete cascade,
  search_text text not null default '',
  contacts_count int not null default 0,
  primary_contact text,
  total_calls int not null default 0,
  responded_calls int not null default 0,
  last_call_at timestamptz,
  last_call_outcome text,
  open_follow_ups int not null default 0,
  next_follow_up_date date,
  next_meeting_at timestamptz,
  next_meeting_confirmation text,
  meetings_total int not null default 0,
  meetings_attended int not null default 0,
  last_meeting_outcome text,
  form_status text,
  proposal_status text,
  proposal_response text,
  negotiation_recorded boolean not null default false,
  last_activity_at timestamptz,
  updated_at timestamptz not null default now()
);
create index lead_rollups_search_trgm on public.lead_rollups using gin (search_text extensions.gin_trgm_ops);
create index lead_rollups_next_fu_idx on public.lead_rollups (next_follow_up_date);
create index lead_rollups_last_call_idx on public.lead_rollups (last_call_at desc);

-- ============ 20261009000002_triggers.sql ============
-- Rollups, timeline activities and audit triggers

-- ---------------------------------------------------------------------------
-- Rollup maintenance
-- ---------------------------------------------------------------------------
create or replace function public.refresh_lead_rollup(p_lead uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_search text;
  v_contacts int;
  v_primary text;
  v_calls int;
  v_resp int;
  v_last_call timestamptz;
  v_last_out text;
  v_open int;
  v_next_fu date;
  v_next_mt timestamptz;
  v_next_conf text;
  v_mt_total int;
  v_mt_att int;
  v_mt_out text;
  v_form text;
  v_prop text;
  v_prop_resp text;
  v_neg boolean;
  v_last_act timestamptz;
begin
  if not exists (select 1 from leads where id = p_lead) then
    return;
  end if;

  select lower(concat_ws(' ', l.name, l.external_lead_id,
           (select string_agg(concat_ws(' ', c.full_name, c.job_title,
                    array_to_string(c.emails, ' '), array_to_string(c.phones, ' ')), ' ')
              from contacts c where c.lead_id = l.id)))
    into v_search from leads l where l.id = p_lead;

  select count(*) into v_contacts from contacts where lead_id = p_lead;
  select coalesce(nullif(c.full_name, ''), c.emails[1], c.phones[1]) into v_primary
    from contacts c where c.lead_id = p_lead
    order by c.is_primary desc, (c.full_name <> '') desc, c.created_at limit 1;

  select count(*), count(*) filter (where o.kind = 'responded')
    into v_calls, v_resp
    from call_attempts a join call_outcomes o on o.key = a.outcome where a.lead_id = p_lead;
  select a.called_at, a.outcome into v_last_call, v_last_out
    from call_attempts a where a.lead_id = p_lead order by a.called_at desc, a.created_at desc limit 1;

  select count(*), min(due_date) into v_open, v_next_fu
    from follow_ups where lead_id = p_lead and status = 'open';

  select scheduled_at, confirmation_status into v_next_mt, v_next_conf
    from meetings where lead_id = p_lead and status = 'scheduled' and scheduled_at >= now()
    order by scheduled_at limit 1;

  select count(*) filter (where status <> 'requested'), count(*) filter (where attendance_status = 'attended')
    into v_mt_total, v_mt_att from meetings where lead_id = p_lead;
  select meeting_outcome into v_mt_out from meetings
    where lead_id = p_lead and attendance_status = 'attended' and meeting_outcome is not null
    order by scheduled_at desc limit 1;

  select status into v_form from commercial_forms where lead_id = p_lead order by created_at desc limit 1;
  select status, coalesce(response_outcome, response_state) into v_prop, v_prop_resp
    from proposals where lead_id = p_lead order by created_at desc limit 1;

  select exists (select 1 from proposals where lead_id = p_lead and response_outcome = 'negotiation')
      or exists (select 1 from meetings where lead_id = p_lead and (meeting_outcome = 'negotiation' or next_step = 'commercial_negotiation'))
    into v_neg;

  select max(occurred_at) into v_last_act from activities where lead_id = p_lead;

  insert into lead_rollups as r (lead_id, search_text, contacts_count, primary_contact, total_calls, responded_calls,
      last_call_at, last_call_outcome, open_follow_ups, next_follow_up_date, next_meeting_at, next_meeting_confirmation,
      meetings_total, meetings_attended, last_meeting_outcome, form_status, proposal_status, proposal_response,
      negotiation_recorded, last_activity_at, updated_at)
  values (p_lead, v_search, v_contacts, v_primary, v_calls, v_resp, v_last_call, v_last_out, v_open, v_next_fu,
      v_next_mt, v_next_conf, v_mt_total, v_mt_att, v_mt_out, v_form, v_prop, v_prop_resp, v_neg, v_last_act, now())
  on conflict (lead_id) do update set
      search_text = excluded.search_text, contacts_count = excluded.contacts_count,
      primary_contact = excluded.primary_contact, total_calls = excluded.total_calls,
      responded_calls = excluded.responded_calls, last_call_at = excluded.last_call_at,
      last_call_outcome = excluded.last_call_outcome, open_follow_ups = excluded.open_follow_ups,
      next_follow_up_date = excluded.next_follow_up_date, next_meeting_at = excluded.next_meeting_at,
      next_meeting_confirmation = excluded.next_meeting_confirmation, meetings_total = excluded.meetings_total,
      meetings_attended = excluded.meetings_attended, last_meeting_outcome = excluded.last_meeting_outcome,
      form_status = excluded.form_status, proposal_status = excluded.proposal_status,
      proposal_response = excluded.proposal_response, negotiation_recorded = excluded.negotiation_recorded,
      last_activity_at = excluded.last_activity_at, updated_at = now();
end $$;
revoke all on function public.refresh_lead_rollup(uuid) from public, anon, authenticated;

create or replace function public.trg_rollup() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_new uuid;
  v_old uuid;
begin
  if tg_op in ('INSERT', 'UPDATE') then v_new := (to_jsonb(new) ->> (case tg_table_name when 'leads' then 'id' else 'lead_id' end))::uuid; end if;
  if tg_op in ('DELETE', 'UPDATE') then v_old := (to_jsonb(old) ->> (case tg_table_name when 'leads' then 'id' else 'lead_id' end))::uuid; end if;
  if v_new is not null then perform public.refresh_lead_rollup(v_new); end if;
  if v_old is not null and v_old is distinct from v_new then perform public.refresh_lead_rollup(v_old); end if;
  return null;
end $$;

create trigger rollup_leads after insert or update of name, external_lead_id on public.leads
  for each row execute function public.trg_rollup();
create trigger rollup_contacts after insert or update or delete on public.contacts
  for each row execute function public.trg_rollup();
create trigger rollup_calls after insert or update or delete on public.call_attempts
  for each row execute function public.trg_rollup();
create trigger rollup_follow_ups after insert or update or delete on public.follow_ups
  for each row execute function public.trg_rollup();
create trigger rollup_meetings after insert or update or delete on public.meetings
  for each row execute function public.trg_rollup();
create trigger rollup_forms after insert or update or delete on public.commercial_forms
  for each row execute function public.trg_rollup();
create trigger rollup_proposals after insert or update or delete on public.proposals
  for each row execute function public.trg_rollup();

-- ---------------------------------------------------------------------------
-- Timeline activities (only verified, user-recorded business events)
-- ---------------------------------------------------------------------------
create or replace function public.log_activity(
  p_lead uuid, p_actor uuid, p_type text, p_summary text,
  p_ref_table text, p_ref_id uuid, p_data jsonb default '{}'::jsonb, p_at timestamptz default now()
) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into activities (lead_id, actor_id, type, occurred_at, summary, ref_table, ref_id, data)
  values (p_lead, p_actor, p_type, coalesce(p_at, now()), p_summary, p_ref_table, p_ref_id, coalesce(p_data, '{}'::jsonb));
  update lead_rollups set last_activity_at = greatest(coalesce(last_activity_at, '-infinity'), coalesce(p_at, now()))
   where lead_id = p_lead;
end $$;
revoke all on function public.log_activity(uuid, uuid, text, text, text, uuid, jsonb, timestamptz) from public, anon, authenticated;

create or replace function public.actor_id() returns uuid
language sql stable as $$
  select coalesce(auth.uid(), nullif(current_setting('app.actor', true), '')::uuid)
$$;

create or replace function public.trg_activity_leads() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    perform log_activity(new.id, coalesce(actor_id(), new.created_by), 'lead_created',
      case when new.source = 'google_sheet' then 'Lead imported from Accord New Data' else 'Lead created' end,
      'leads', new.id, jsonb_build_object('source', new.source));
  else
    if new.pipeline_stage is distinct from old.pipeline_stage then
      perform log_activity(new.id, actor_id(), 'pipeline_change',
        'Pipeline: ' || old.pipeline_stage || ' → ' || new.pipeline_stage,
        'leads', new.id, jsonb_build_object('from', old.pipeline_stage, 'to', new.pipeline_stage));
    end if;
    if new.temperature is distinct from old.temperature then
      perform log_activity(new.id, actor_id(), 'temperature_change',
        'Temperature: ' || old.temperature || ' → ' || new.temperature,
        'leads', new.id, jsonb_build_object('from', old.temperature, 'to', new.temperature));
    end if;
  end if;
  return null;
end $$;
create trigger activity_leads after insert or update of pipeline_stage, temperature on public.leads
  for each row execute function public.trg_activity_leads();

create or replace function public.trg_activity_calls() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_label text; v_kind text;
begin
  select label, kind into v_label, v_kind from call_outcomes where key = new.outcome;
  perform log_activity(new.lead_id, new.user_id, 'call',
    v_label || coalesce(' — ' || nullif(btrim(new.notes), ''), ''),
    'call_attempts', new.id,
    jsonb_build_object('outcome', new.outcome, 'kind', v_kind, 'sub_outcome', new.sub_outcome), new.called_at);
  return null;
end $$;
create trigger activity_calls after insert on public.call_attempts
  for each row execute function public.trg_activity_calls();

create or replace function public.trg_activity_follow_ups() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    perform log_activity(new.lead_id, coalesce(actor_id(), new.created_by), 'follow_up_created',
      'Follow-up due ' || new.due_date || coalesce(' — ' || nullif(btrim(new.notes), ''), ''),
      'follow_ups', new.id, jsonb_build_object('due_date', new.due_date, 'origin', new.origin));
  else
    if old.status <> 'completed' and new.status = 'completed' then
      perform log_activity(new.lead_id, coalesce(actor_id(), new.completed_by), 'follow_up_completed',
        'Follow-up completed (was due ' || new.due_date || ')', 'follow_ups', new.id,
        jsonb_build_object('due_date', new.due_date));
    elsif new.due_date is distinct from old.due_date and new.status = 'open' then
      perform log_activity(new.lead_id, actor_id(), 'follow_up_rescheduled',
        'Follow-up moved ' || old.due_date || ' → ' || new.due_date, 'follow_ups', new.id,
        jsonb_build_object('from', old.due_date, 'to', new.due_date));
    end if;
  end if;
  return null;
end $$;
create trigger activity_follow_ups after insert or update on public.follow_ups
  for each row execute function public.trg_activity_follow_ups();

create or replace function public.trg_activity_meetings() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_who uuid := coalesce(actor_id(), new.created_by);
begin
  if tg_op = 'INSERT' then
    if new.status = 'requested' then
      perform log_activity(new.lead_id, v_who, 'meeting_requested', 'Meeting requested', 'meetings', new.id, '{}');
    else
      perform log_activity(new.lead_id, v_who, 'meeting_scheduled',
        'Meeting scheduled for ' || to_char(new.scheduled_at at time zone 'Africa/Cairo', 'YYYY-MM-DD HH24:MI')
          || ' (' || new.confirmation_status || ')',
        'meetings', new.id,
        jsonb_build_object('scheduled_at', new.scheduled_at, 'type', new.meeting_type,
          'rescheduled_from', new.rescheduled_from_id, 'follows', new.follows_meeting_id));
    end if;
    return null;
  end if;

  if old.status = 'requested' and new.status = 'scheduled' then
    perform log_activity(new.lead_id, v_who, 'meeting_scheduled',
      'Meeting scheduled for ' || to_char(new.scheduled_at at time zone 'Africa/Cairo', 'YYYY-MM-DD HH24:MI'),
      'meetings', new.id, jsonb_build_object('scheduled_at', new.scheduled_at));
  end if;
  if new.confirmation_status is distinct from old.confirmation_status and new.confirmation_status = 'confirmed' then
    perform log_activity(new.lead_id, v_who, 'meeting_confirmed', 'Meeting confirmed', 'meetings', new.id, '{}');
  end if;
  if new.attendance_status is distinct from old.attendance_status then
    if new.attendance_status = 'attended' then
      perform log_activity(new.lead_id, v_who, 'meeting_attended', 'Meeting attended', 'meetings', new.id, '{}');
    elsif new.attendance_status = 'not_attended' then
      perform log_activity(new.lead_id, v_who, 'meeting_not_attended',
        'Meeting not attended — ' || coalesce(new.not_attended_reason, 'no reason'),
        'meetings', new.id, jsonb_build_object('reason', new.not_attended_reason));
    end if;
  end if;
  if new.status is distinct from old.status then
    if new.status = 'rescheduled' then
      perform log_activity(new.lead_id, v_who, 'meeting_rescheduled', 'Meeting rescheduled', 'meetings', new.id,
        jsonb_build_object('replacement', new.next_meeting_id));
    elsif new.status = 'cancelled' then
      perform log_activity(new.lead_id, v_who, 'meeting_cancelled', 'Meeting cancelled', 'meetings', new.id, '{}');
    end if;
  end if;
  if coalesce(btrim(new.minutes_of_meeting), '') <> '' and coalesce(btrim(old.minutes_of_meeting), '') = '' then
    perform log_activity(new.lead_id, v_who, 'minutes_added', 'Minutes of meeting recorded', 'meetings', new.id,
      jsonb_build_object('outcome', new.meeting_outcome, 'next_step', new.next_step));
  end if;
  return null;
end $$;
create trigger activity_meetings after insert or update on public.meetings
  for each row execute function public.trg_activity_meetings();

create or replace function public.trg_activity_forms() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_who uuid := coalesce(actor_id(), new.created_by);
begin
  if tg_op = 'INSERT' then
    perform log_activity(new.lead_id, v_who, case new.status when 'sent' then 'form_sent' when 'completed' then 'form_completed' else 'form_required' end,
      'Information form — ' || new.status, 'commercial_forms', new.id, jsonb_build_object('status', new.status));
  elsif new.status is distinct from old.status then
    perform log_activity(new.lead_id, v_who,
      case new.status when 'sent' then 'form_sent' when 'completed' then 'form_completed' else 'form_updated' end,
      'Information form — ' || old.status || ' → ' || new.status, 'commercial_forms', new.id,
      jsonb_build_object('from', old.status, 'to', new.status));
  end if;
  return null;
end $$;
create trigger activity_forms after insert or update on public.commercial_forms
  for each row execute function public.trg_activity_forms();

create or replace function public.trg_activity_proposals() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_who uuid := coalesce(actor_id(), new.created_by);
begin
  if tg_op = 'INSERT' then
    perform log_activity(new.lead_id, v_who, 'proposal_prepared',
      'Proposal PR-' || lpad(new.proposal_no::text, 5, '0') || ' — ' || new.status, 'proposals', new.id,
      jsonb_build_object('status', new.status));
    return null;
  end if;
  if new.status is distinct from old.status then
    if new.status = 'sent' then
      perform log_activity(new.lead_id, v_who, 'proposal_sent', 'Proposal sent', 'proposals', new.id,
        jsonb_build_object('sent_on', new.sent_on));
    else
      perform log_activity(new.lead_id, v_who, 'proposal_status_changed',
        'Proposal status: ' || old.status || ' → ' || new.status, 'proposals', new.id,
        jsonb_build_object('from', old.status, 'to', new.status));
    end if;
  end if;
  if new.response_outcome is distinct from old.response_outcome and new.response_outcome is not null then
    perform log_activity(new.lead_id, v_who, 'proposal_response', 'Client response: ' || new.response_outcome,
      'proposals', new.id, jsonb_build_object('outcome', new.response_outcome, 'response_on', new.response_on));
    if new.response_outcome = 'negotiation' then
      perform log_activity(new.lead_id, v_who, 'negotiation', 'Negotiation recorded', 'proposals', new.id, '{}');
    end if;
  end if;
  return null;
end $$;
create trigger activity_proposals after insert or update on public.proposals
  for each row execute function public.trg_activity_proposals();

-- ---------------------------------------------------------------------------
-- Generic audit trigger
-- ---------------------------------------------------------------------------
create or replace function public.audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  o jsonb; n jsonb; k text;
  od jsonb := '{}'::jsonb; nd jsonb := '{}'::jsonb;
  v_actor uuid; v_email text; v_action text; v_id text;
begin
  if coalesce(current_setting('app.skip_audit', true), '') = '1' then
    return null;
  end if;
  v_actor := actor_id();
  select email into v_email from profiles where id = v_actor;

  if tg_op = 'INSERT' then
    n := to_jsonb(new); v_id := coalesce(n ->> 'id', n ->> 'key'); v_action := 'create'; nd := n;
  elsif tg_op = 'DELETE' then
    o := to_jsonb(old); v_id := coalesce(o ->> 'id', o ->> 'key'); v_action := 'delete'; od := o;
  else
    o := to_jsonb(old); n := to_jsonb(new); v_id := coalesce(n ->> 'id', n ->> 'key'); v_action := 'update';
    for k in select jsonb_object_keys(n) loop
      if k <> 'updated_at' and (n -> k) is distinct from (o -> k) then
        od := od || jsonb_build_object(k, o -> k);
        nd := nd || jsonb_build_object(k, n -> k);
      end if;
    end loop;
    if nd = '{}'::jsonb then return null; end if;
    -- semantic action names for the events the business cares about
    if tg_table_name = 'profiles' and nd ? 'role' then v_action := 'role_changed';
    elsif tg_table_name = 'profiles' and nd ? 'active' then v_action := case when (nd ->> 'active')::boolean then 'user_activated' else 'user_deactivated' end;
    elsif tg_table_name = 'leads' and nd ? 'pipeline_stage' then v_action := 'pipeline_changed';
    elsif tg_table_name = 'leads' and nd ? 'temperature' then v_action := 'temperature_changed';
    elsif tg_table_name = 'meetings' and nd ? 'confirmation_status' then v_action := 'meeting_confirmation';
    elsif tg_table_name = 'meetings' and nd ? 'attendance_status' then v_action := 'meeting_attendance';
    elsif tg_table_name = 'meetings' and nd ? 'minutes_of_meeting' then v_action := 'minutes_edited';
    elsif tg_table_name = 'meetings' and (nd ? 'scheduled_at' or nd ? 'status') then v_action := 'meeting_changed';
    elsif tg_table_name = 'commercial_forms' and nd ? 'status' then v_action := 'form_status_changed';
    elsif tg_table_name = 'proposals' and nd ? 'response_outcome' then v_action := 'proposal_response';
    elsif tg_table_name = 'proposals' and (nd ->> 'status') = 'sent' then v_action := 'proposal_sent';
    elsif tg_table_name = 'proposals' and nd ? 'status' then v_action := 'proposal_status_changed';
    elsif tg_table_name = 'call_attempts' then v_action := 'call_edited';
    end if;
  end if;

  if tg_table_name = 'call_attempts' and tg_op = 'DELETE' then v_action := 'call_deleted'; end if;
  if tg_table_name = 'profiles' and tg_op = 'INSERT' then v_action := 'user_created'; end if;
  if tg_table_name = 'user_targets' then v_action := case tg_op when 'INSERT' then 'target_set' when 'DELETE' then 'target_deleted' else 'target_changed' end; end if;
  if tg_table_name = 'settings' then v_action := 'setting_changed'; end if;

  insert into audit_logs (actor_id, actor_email, entity, entity_id, action, old_value, new_value)
  values (v_actor, v_email, tg_table_name, v_id, v_action,
          case when tg_op = 'INSERT' then null else od end,
          case when tg_op = 'DELETE' then null else nd end);
  return null;
end $$;

-- everything except high-volume call inserts is audited (call edits/deletes are)
create trigger audit_leads after insert or update or delete on public.leads for each row execute function public.audit_row();
create trigger audit_contacts after insert or update or delete on public.contacts for each row execute function public.audit_row();
create trigger audit_calls after update or delete on public.call_attempts for each row execute function public.audit_row();
create trigger audit_follow_ups after insert or update or delete on public.follow_ups for each row execute function public.audit_row();
create trigger audit_meetings after insert or update or delete on public.meetings for each row execute function public.audit_row();
create trigger audit_forms after insert or update or delete on public.commercial_forms for each row execute function public.audit_row();
create trigger audit_proposals after insert or update or delete on public.proposals for each row execute function public.audit_row();
create trigger audit_targets after insert or update or delete on public.user_targets for each row execute function public.audit_row();
create trigger audit_profiles after insert or update or delete on public.profiles for each row execute function public.audit_row();
create trigger audit_settings after insert or update or delete on public.settings for each row execute function public.audit_row();
create trigger audit_pipeline_stages after insert or update or delete on public.pipeline_stages for each row execute function public.audit_row();
create trigger audit_call_outcomes after insert or update or delete on public.call_outcomes for each row execute function public.audit_row();
create trigger audit_projects after update or delete on public.projects for each row execute function public.audit_row();
create trigger audit_attachments after insert or delete on public.attachments for each row execute function public.audit_row();

-- ============ 20261009000003_rls.sql ============
-- Row Level Security. Default deny. Anonymous has NO table access at all.
-- Access model:
--   admin        : full management
--   bd_executive : reads the shared lead pool; writes own calls / follow-ups / meetings / forms / proposals;
--                  may edit leads they own or unassigned leads
--   viewer       : read-only
--   inactive / no profile / anon : nothing

revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke all on all functions in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on functions from anon;
alter default privileges in schema public revoke all on sequences from anon;

do $$
declare t text;
begin
  foreach t in array array[
    'pipeline_stages','call_outcomes','activity_types','settings','profiles','leads','contacts',
    'call_sessions','call_attempts','user_targets','follow_ups','meetings','commercial_forms',
    'proposals','attachments','projects','activities','sync_runs','sync_errors','audit_logs','lead_rollups']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from authenticated', t);
  end loop;
end $$;

-- authenticated: table privileges are granted narrowly; RLS then filters rows
grant select on public.pipeline_stages, public.call_outcomes, public.activity_types, public.settings,
  public.profiles, public.leads, public.contacts, public.call_sessions, public.call_attempts, public.user_targets,
  public.follow_ups, public.meetings, public.commercial_forms, public.proposals, public.attachments,
  public.projects, public.activities, public.lead_rollups to authenticated;
grant select on public.sync_runs, public.sync_errors, public.audit_logs to authenticated;
grant insert, update, delete on public.pipeline_stages, public.call_outcomes, public.settings,
  public.profiles, public.leads, public.contacts, public.call_sessions, public.call_attempts, public.user_targets,
  public.follow_ups, public.meetings, public.commercial_forms, public.proposals, public.attachments,
  public.projects to authenticated;
grant usage on sequence public.proposal_seq to authenticated;

-- reference / config ---------------------------------------------------------
create policy ref_read on public.pipeline_stages for select to authenticated using (public.is_member());
create policy ref_write on public.pipeline_stages for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy ref_read on public.call_outcomes for select to authenticated using (public.is_member());
create policy ref_write on public.call_outcomes for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy ref_read on public.activity_types for select to authenticated using (public.is_member());
create policy ref_read on public.settings for select to authenticated using (public.is_member());
create policy ref_write on public.settings for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- profiles: members see colleagues; only admins (or the service role via Edge Function) write
create policy profiles_read on public.profiles for select to authenticated using (public.is_member() or id = auth.uid());
create policy profiles_admin_write on public.profiles for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- leads ----------------------------------------------------------------------
create policy leads_read on public.leads for select to authenticated using (public.is_member());
create policy leads_insert on public.leads for insert to authenticated
  with check (public.is_staff() and created_by = auth.uid() and (owner_id is null or owner_id = auth.uid() or public.is_admin()));
create policy leads_update on public.leads for update to authenticated
  using (public.is_admin() or (public.is_staff() and (owner_id is null or owner_id = auth.uid())))
  with check (public.is_admin() or (public.is_staff() and (owner_id is null or owner_id = auth.uid())));
create policy leads_delete on public.leads for delete to authenticated using (public.is_admin());

create policy rollups_read on public.lead_rollups for select to authenticated using (public.is_member());

-- contacts: writable by whoever can write the lead
create policy contacts_read on public.contacts for select to authenticated using (public.is_member());
create policy contacts_write on public.contacts for all to authenticated
  using (public.is_admin() or (public.is_staff() and exists (select 1 from public.leads l where l.id = lead_id and (l.owner_id is null or l.owner_id = auth.uid()))))
  with check (public.is_admin() or (public.is_staff() and exists (select 1 from public.leads l where l.id = lead_id and (l.owner_id is null or l.owner_id = auth.uid()))));

-- calls: anyone active reads lead history; users log calls as themselves; edit/delete own same-day only
create policy calls_read on public.call_attempts for select to authenticated using (public.is_member());
create policy calls_insert on public.call_attempts for insert to authenticated
  with check (public.is_staff() and (user_id = auth.uid() or public.is_admin()));
create policy calls_update on public.call_attempts for update to authenticated
  using (public.is_admin() or (public.is_staff() and user_id = auth.uid() and public.cairo_date(called_at) = public.cairo_today()))
  with check (public.is_admin() or (public.is_staff() and user_id = auth.uid() and public.cairo_date(called_at) = public.cairo_today()));
create policy calls_delete on public.call_attempts for delete to authenticated
  using (public.is_admin() or (public.is_staff() and user_id = auth.uid() and public.cairo_date(called_at) = public.cairo_today()));

create policy sessions_read on public.call_sessions for select to authenticated using (user_id = auth.uid() or public.is_admin());
create policy sessions_write on public.call_sessions for all to authenticated
  using (public.is_staff() and (user_id = auth.uid() or public.is_admin()))
  with check (public.is_staff() and (user_id = auth.uid() or public.is_admin()));

-- targets: admin manages; users read their own
create policy targets_read on public.user_targets for select to authenticated using (public.is_admin() or (public.is_member() and user_id = auth.uid()));
create policy targets_write on public.user_targets for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- follow-ups / meetings / forms / proposals: staff create; owner (or creator) or admin edits
